def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find connected non-background, non-5 components in the original grid.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or g[r][c] == 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                cr, cc = stack.pop()
                comp.append((cr, cc))
                for nr, nc in ((cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                        g[nr][nc] not in (0, 5) and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(comp)

    # Horizontal runs of 5 extend the adjacent vertical color pattern sideways.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and g[r][c] == 5:
                c += 1
            end = c - 1
            if end - start + 1 < 2:
                continue

            touching = []
            for comp in components:
                if any((rr == r - 1 or rr == r + 1) and start <= cc <= end
                       for rr, cc in comp):
                    touching.append(comp)
            if not touching:
                continue
            comp = max(touching, key=len)
            rmin = min(rr for rr, _ in comp)
            rmax = max(rr for rr, _ in comp)
            cmin = min(cc for _, cc in comp)
            for rr in range(rmin, rmax + 1):
                source = next((g[rr][cc] for cr, cc in comp if cr == rr), None)
                if source is not None:
                    for cc in range(start, end + 1):
                        g[rr][cc] = source

    # Vertical runs of 5 extend the adjacent horizontal pattern along the run.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and g[r][c] == 5:
                r += 1
            end = r - 1
            if end - start + 1 < 2:
                continue

            touching = []
            for comp in components:
                if any((cc == c - 1 or cc == c + 1) and start <= rr <= end
                       for rr, cc in comp):
                    touching.append(comp)
            if not touching:
                continue
            comp = max(touching, key=len)
            rmin = min(rr for rr, _ in comp)
            rmax = max(rr for rr, _ in comp)
            cmin = min(cc for _, cc in comp)
            cmax = max(cc for _, cc in comp)
            motif_h = rmax - rmin + 1
            for rr in range(start, end + 1):
                source_r = rmin + (rr - rmin) % motif_h
                for cc in range(cmin, cmax + 1):
                    if any(cr == source_r and c0 == cc for cr, c0 in comp):
                        g[rr][cc] = grid[source_r][cc]

    return g
